import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"63、【既濟】 離下坎上","description":"周易口訣義 - 63、【既濟】 離下坎上","frontmatter":{"title":"63、【既濟】 離下坎上","description":"周易口訣義 - 63、【既濟】 離下坎上"},"headers":[],"relativePath":"classics/koujueyi/065.md","filePath":"classics/koujueyi/065.md"}'),r={name:"classics/koujueyi/065.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_63、【既濟】-離下坎上" tabindex="-1">63、【既濟】 離下坎上 <a class="header-anchor" href="#_63、【既濟】-離下坎上" aria-label="Permalink to “63、【既濟】 離下坎上”">​</a></h1><p>彖曰：「既濟亨小」者，亨也。「利貞」，剛柔正而位當也。「初吉」，柔得中也。終止則亂，其道窮也。</p><p>象曰：水在火上，既濟，君子以思患而豫防之。</p><p>初九：曳其輪，濡其尾，無咎。</p><p>象曰：「曳其輪」，義無咎也。</p><p>六二：婦喪其茀，勿逐，七日得。</p><p>象曰：「七日得」，以中道也。</p><p>九三：高宗伐鬼方，三年克之，小人勿用。</p><p>象曰：「三年克之」，憊也。</p><p>六四，繻有衣袽，終日戒。</p><p>象曰：「終日戒」，有所疑也。</p><p>九五，東鄰殺牛，不如西鄰之礿祭，實受其福。</p><p>象曰：「東鄰殺牛」，不如西鄰之時也；「實受其福」，吉大來也。</p><p>上六，濡其首，厲。</p><p>象曰：「濡其首厲」，何可久也！</p><p>解讀</p><p>「既濟，亨小利貞」者，既，盡也；濟，渡也；剛柔得正，上下相應，故曰「既濟」也。萬物盡皆濟渡，若小者不通，則無盡濟之理。今小者猶尚通亨，則柔大之物自然獲濟，故曰「亨小」也。物既盡濟，非正不可，故曰「利貞」。「初吉終亂」者，此設戒之辭。當既濟之時，若能戒慎謙守，不為驕恣，則既濟無窮，安有危亂及己！若其不能居安慮危，慎終如始，則既濟其極，危亂至矣。故王傳雲「終亂不如自亂，由止故亂」是也。</p><p>象曰「水在火上，既濟」者，孔義雲：「水在火上，炊爨之象，飲食以之而成，性命以之而濟，是故既濟象也。」「君子以思患豫防之」者，處既濟之時，舉事合宜，恣情所欲，固當恭儉保守，存不忘亡，思慮後患，豫為防慎，故書雲「制治於未亂，保邦於未危」是也。</p><p>「初九，曳其輪，濡其尾，無咎」者，初九處既濟之初，是始濟渡也。始濟險難，未至乾燥之地，猶拖曳其輪，濡溼其尾，言其勞苦，方始獲濟，其於義理，安有咎哉？故曰「無咎」也。</p><p>「六二，婦喪其茀，勿逐，七日得」者，茀者，婦人之首飾也。六二居中履正，而應於五，雖與初三相近，情不相得，遂被初三相奪。以人事明之，其猶貞潔之婦，容儀光麗，夫暫不在，遂被他人侵陵，頭上花飾，強為竊奪，故曰「婦喪其茀」。稱「婦」者，明己自有夫而被見侵。當既濟之時，法令明峻，不容邪道，婦既執貞如此，眾尚節志，皆願助之，假使逃竄，勢不能久，不過七日，必見執獲，故曰「勿逐，七日得」也。</p><p>「九三，高宗伐鬼方，三年克之，小人勿用」者，處既濟之時，居文明之末，將入險難，是居衰而能濟。其猶殷王高宗諒陰三年，盛德中興，克伐鬼方，以其盛德始興，不能即勝，故三年已後，乃始克勝，故曰「三年克之」也。高宗者，武丁之號，殷之賢王，挺濟衰世，能伐遠方。若小人居之，必致危亂，不可任用，故曰「小人勿用」也。</p><p>「六四，繻有衣袽，終日戒」者，繻宜曰濡，是沾溼之義；袽者，衣敝爛者，可以塞漏舟也。六四處得其位，而與三五相近，情不相得，常慮危患及身，如舟之穿漏而能得濟渡者，必須敝爛之衣塞之，免為濡溺，方遂獲濟，故曰「濡有衣袽」也。鄰不親而得全者，須防戒得免，故曰「終日戒」也。</p><p>「九五，東鄰殺牛，不如西鄰之礿祭，實受其福」者，牛，祭之盛也。礿是殷時春祭之名，四時最薄之祭也。九五處既濟之時，得居尊位，天下盡皆獲濟，亦何所營為？喻天下太平，不勞思慮，其所務者，莫過祭祀，祭祀之本，莫過修德。今九五履正居中，修德如此，但可礿祭省薄，精誠致敬，合時之宜，則神明降福。假使東鄰殺牛，豐厚之盛，神靈不饗，不如西鄰薄祭，吉福大來。此蘋蘩可薦之義，故惟德是馨矣。</p><p>上六：濡其首，厲者，處既濟之極，物極則反，遂至於未濟者，則首先犯焉。若既濟之時，守謙保位，無為無事，安能有咎？今既進而不已，遂遇危難，故濡其首也。既被濡者，將陷於難，危莫甚焉，故曰「濡其首厲」也。</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
